Account.ready.then(user=>{document.getElementById('identity').textContent='@'+user.username;const role={admin:'Administrator',editor:'Editor',reviewer:'Reviewer',learner:'Learner'}[user.role]||user.role;document.getElementById('profile-role').textContent=role;document.getElementById('security-role').textContent=role;document.getElementById('security-username').textContent=user.username;document.getElementById('logout').onclick=async()=>{await Account.request('/api/logout',{});location.href='/login.html'};document.getElementById('import-browser').onclick=async()=>{const button=document.getElementById('import-browser'),status=document.getElementById('account-message');button.disabled=true;try{const notes={};for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key.startsWith('shee-note:'))notes[key.slice(10)]=localStorage.getItem(key)}const collections=JSON.parse(localStorage.getItem('shee-collections-v1')||'[]');const result=await Account.request('/api/import-browser',{notes,collections});status.textContent='Imported '+result.notes_added+' notes. Your account now has '+result.collections+' collections. Open the question set page to use them.'}catch(e){status.textContent=e.message}finally{button.disabled=false}}}).catch(()=>{});

Account.ready.then(()=>{document.getElementById('password-form').onsubmit=async e=>{e.preventDefault();const status=document.getElementById('password-status');try{await Account.request('/api/password',{current:document.getElementById('current-password').value,password:document.getElementById('new-password').value});e.target.reset();status.textContent='Password changed. Other sessions are signed out.'}catch(err){status.textContent=err.message}}}).catch(()=>{});

Account.ready.then(async user=>{
 const $=id=>document.getElementById(id);let profile=await Account.request('/api/profile'),image=profile.photo||'',photoLoading=false,saving=false;
 function dirty(){return image!==(profile.photo||'')||$('confirm-stage').checked||['name','real_name','programme','entry_year','stage','institution','specialty','status'].some(k=>$('profile-'+k).value!==String(profile[k]??''))}function updateButtons(){$('save-profile').disabled=photoLoading||saving||!dirty();$('cancel-profile').disabled=photoLoading||saving;$('change-photo').disabled=photoLoading||saving;$('picture-avatar-button').disabled=photoLoading||saving;$('remove-photo').disabled=photoLoading||saving||!image;}
 function preview(){const box=$('profile-avatar');box.replaceChildren();if(image){const img=document.createElement('img');img.src=image;img.alt='Your profile picture';box.append(img)}else box.textContent=Array.from((user.username||'?').trim())[0].toUpperCase();}
 function load(){for(const key of ['name','real_name','programme','entry_year','stage','institution','specialty','status'])$('profile-'+key).value=profile[key]??'';$('profile-entry_year').max=new Date().getFullYear()+1;$('confirm-stage').checked=false;$('education-review').textContent=profile.review_due?'Please review your current year or training stage and confirm it below.':profile.next_review?'Next annual review: '+profile.next_review+'.':'Confirm your stage when ready to start the annual review reminder.';$('summary-name').textContent=profile.real_name||profile.name;preview();updateButtons()}
 load();$('change-photo').onclick=()=>$('profile-photo').click();$('profile-form').oninput=updateButtons;$('profile-form').onchange=updateButtons;$('cancel-profile').onclick=()=>{image=profile.photo||'';$('profile-photo').value='';$('photo-status').textContent='';$('profile-message').textContent='';load()};window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue=''}});$('profile-name').addEventListener('input',preview);
 $('picture-avatar-button').onclick=async()=>{if(photoLoading||saving)return;photoLoading=true;updateButtons();try{const chosen=await AvatarPicker.open({username:user.username});if(chosen!==null){image=chosen;$('profile-photo').value='';preview();$('photo-status').textContent=image!==(profile.photo||'')?'Picture changed — save changes below to apply it.':'';}}catch(e){$('photo-status').textContent='Could not open the cartoon picker.';}finally{photoLoading=false;updateButtons()}};

 $('remove-photo').onclick=()=>{image='';$('profile-photo').value='';preview();$('photo-status').textContent='Photo will be removed when you save.';updateButtons()};
 $('profile-photo').onchange=async()=>{const file=$('profile-photo').files[0];if(!file)return;photoLoading=true;updateButtons();$('save-profile').disabled=true;$('remove-photo').disabled=true;try{if(!['image/png','image/jpeg'].includes(file.type)||file.size>8*1024*1024)throw Error('Choose a JPEG or PNG smaller than 8 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');const ratio=Math.min(1,256/img.width,256/img.height);canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);image=canvas.toDataURL('image/jpeg',.85);}finally{URL.revokeObjectURL(url)}preview();$('photo-status').textContent='Preview ready. Save profile to apply it.';}catch(e){$('photo-status').textContent=e.message}finally{photoLoading=false;updateButtons()}};
 $('profile-form').onsubmit=async event=>{event.preventDefault();if(photoLoading||saving)return;saving=true;updateButtons();try{const data={revision:profile.revision,photo:image,confirm_stage:$('confirm-stage').checked};for(const k of ['name','real_name','programme','stage','institution','specialty','status'])data[k]=$('profile-'+k).value;data.entry_year=$('profile-entry_year').value===''?null:Number($('profile-entry_year').value);profile=await Account.request('/api/profile',data);image=profile.photo||'';user.name=profile.name;Account.updateProfile(profile);$('photo-status').textContent='';load();$('identity').textContent='@'+user.username;$('profile-message').textContent='Profile saved.';}catch(e){$('profile-message').textContent=e.message}finally{saving=false;updateButtons()}};
}).catch(e=>{const box=document.getElementById('profile-message');if(box)box.textContent='Could not load your profile. '+e.message;document.getElementById('save-profile').disabled=true});
